DROP TABLE IF EXISTS supply_chain_shipments;
CREATE TABLE supply_chain_shipments (
    shipment_id VARCHAR(255) PRIMARY KEY,
    batch_id VARCHAR(255),
    product_id VARCHAR(255),
    origin_warehouse_id VARCHAR(255),
    destination_country VARCHAR(255),
    carrier VARCHAR(255),
    ship_date VARCHAR(255),
    delivery_date VARCHAR(255),
    quantity_shipped BIGINT,
    shipment_status VARCHAR(255),
    CONSTRAINT fk_supply_chain_shipments_product FOREIGN KEY (product_id) REFERENCES erp_product_master(product_id)
);

